application/json.schema:
{
  "title": "Wikipedia, exchange rates and Treasury input",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "mode": {
      "title": "Mode",
      "type": "string",
      "enum": [
        "wiki",
        "fx",
        "treasury"
      ],
      "editor": "select",
      "description": "Wikipedia search, ECB euro exchange rates, or U.S. Treasury par yields.",
      "default": "wiki",
      "prefill": "wiki"
    },
    "q": {
      "title": "Wikipedia search",
      "type": "string",
      "editor": "textfield",
      "description": "Article search (mode=wiki).",
      "prefill": "European Central Bank"
    },
    "lang": {
      "title": "Language",
      "type": "string",
      "editor": "textfield",
      "description": "Wikipedia language edition, default en.",
      "default": "en"
    },
    "limit": {
      "title": "Limit",
      "type": "integer",
      "editor": "number",
      "description": "Wikipedia result cap, 1-10.",
      "default": 2,
      "prefill": 2,
      "minimum": 1,
      "maximum": 10
    },
    "full": {
      "title": "Full article",
      "type": "boolean",
      "editor": "checkbox",
      "description": "Return full article text instead of the intro.",
      "default": false
    },
    "date": {
      "title": "Date",
      "type": "string",
      "editor": "textfield",
      "description": "YYYY-MM-DD for a historical FX or Treasury snapshot."
    },
    "base": {
      "title": "FX base",
      "type": "string",
      "editor": "textfield",
      "description": "ISO currency, default EUR.",
      "default": "EUR"
    },
    "symbols": {
      "title": "FX symbols",
      "type": "string",
      "editor": "textfield",
      "description": "Optional comma-separated currency codes, for example USD,GBP,JPY."
    },
    "amount": {
      "title": "Amount",
      "type": "number",
      "editor": "number",
      "description": "Optional amount to convert from the base currency."
    }
  },
  "required": [
    "mode"
  ]
}

